def embedding_client(settings: Settings, request: EmbeddingRequest) -> LLMClient:
    if settings.llm_mode != "fake":
        return create_llm_client(settings)
    vectors = tuple(
        tuple(
            float(any(word in content.lower() for word in words))
            for words in (
                ("payment", "支付", "5xx", "连接池"),
                ("network", "网络", "dns"),
                ("capacity", "容量", "磁盘"),
            )
        )
        + (0.1,)
